package com.smartmanager.nativeapp;
/** Non-secret printable card layout settings. */
public final class CardTemplate { public final String id,name,imageUri;public final int paperW,paperH,rows,columns,margin,gap;public final boolean showUser,showPassword,showProfile,showSerial;public CardTemplate(String i,String n,int w,int h,int r,int c,int m,int g,boolean u,boolean p,boolean f,boolean s){this(i,n,"",w,h,r,c,m,g,u,p,f,s);}public CardTemplate(String i,String n,String image,int w,int h,int r,int c,int m,int g,boolean u,boolean p,boolean f,boolean s){id=i;name=n;imageUri=image==null?"":image;paperW=Math.max(1,w);paperH=Math.max(1,h);rows=Math.max(1,r);columns=Math.max(1,c);margin=Math.max(0,m);gap=Math.max(0,g);showUser=u;showPassword=p;showProfile=f;showSerial=s;}public int perPage(){return rows*columns;}public int pages(int count){return count<=0?0:(count+perPage()-1)/perPage();}}
